#include <cstdio>
#include <vector>
#include <string>
#include <queue>
#include <algorithm>
#include <iostream>

struct Node {
    long long v;
    Node *l = nullptr, *r = nullptr;
};

Node* buildTree(const std::vector<std::string> &t) {
    if (t.empty() || t[0] == "null") return nullptr;
    Node *root = new Node{std::stoll(t[0])};
    std::queue<Node*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < t.size()) {
        Node *cur = q.front(); q.pop();
        if (i < t.size()) {
            if (t[i] != "null") { cur->l = new Node{std::stoll(t[i])}; q.push(cur->l); }
            ++i;
        }
        if (i < t.size()) {
            if (t[i] != "null") { cur->r = new Node{std::stoll(t[i])}; q.push(cur->r); }
            ++i;
        }
    }
    return root;
}

int minDepth(Node *n) {
    if (!n) return 0;
    if (!n->l && !n->r) return 1;          // 叶子
    if (!n->l) return 1 + minDepth(n->r);  // 不能取 min
    if (!n->r) return 1 + minDepth(n->l);
    return 1 + std::min(minDepth(n->l), minDepth(n->r));
}

int main() {
    std::vector<std::string> tok;
    std::string t;
    while (std::cin >> t) tok.push_back(t);
    if (tok.empty()) tok.push_back("null");
    printf("%d\n", minDepth(buildTree(tok)));
    return 0;
}
